<?php
namespace App\Livewire\Admin;
use App\Domain\Audit\Services\AuditRecorder;use App\Models\SystemSetting;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')]
class SecuritySettings extends Component{public int $privileged_mfa_minutes=15,$session_idle_minutes=30,$download_rate_per_minute=20,$export_row_threshold=10000;public function mount():void{abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'system.configure'),403);foreach(['privileged_mfa_minutes','session_idle_minutes','download_rate_per_minute','export_row_threshold'] as $key){$v=SystemSetting::where('group','security')->where('key',$key)->first()?->value;if($v!==null)$this->$key=(int)$v;}}public function save(AuditRecorder $audit):void{$data=$this->validate(['privileged_mfa_minutes'=>['required','integer','min:5','max:60'],'session_idle_minutes'=>['required','integer','min:5','max:240'],'download_rate_per_minute'=>['required','integer','min:1','max:500'],'export_row_threshold'=>['required','integer','min:100','max:1000000']]);foreach($data as $key=>$value)SystemSetting::updateOrCreate(['group'=>'security','key'=>$key],['value'=>$value,'is_sensitive'=>false,'updated_by'=>auth()->id()]);$audit->record('SECURITY_SETTINGS_UPDATED','SECURITY','SUCCESS',auth()->user(),['new_values'=>$data]);session()->flash('success','Security settings updated.');}public function render(){return view('livewire.admin.security-settings');}}
